#!/usr/bin/env bash
# Lane 3 — In-memory SELECT throughput.
#
# Measurement method (deterministic, reproducible):
#   * workload.sql (generated by generate-corpus.sh, seed 0xFACEFEED) creates
#     a :memory: table with 10 000 rows then runs 100 000 random
#     point-SELECTs (by primary key). The SELECT IDs are deterministic so
#     every target does identical work.
#   * Wall-clock the whole script, subtract the setup fraction measured
#     separately, report selects-per-second.
#   * Because setup cost is identical across targets (same 10 000 INSERTs),
#     we report the *combined* wall clock divided by 100 000 SELECTs. That
#     slightly pessimizes all targets equally — safe for apples-to-apples.
#   * Median of 5 runs, 1 warmup.
#
# Output: select-in-memory,<target>,<selects_per_second>,selects_per_second,<iso8601>

set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck disable=SC1091
source "$SCRIPT_DIR/../_lib.sh"

LANE_NAME="select-in-memory"
parse_target_flag "$@"

WORKLOAD="$SCRIPT_DIR/workload.sql"
if [[ ! -f "$WORKLOAD" ]]; then
    "$SCRIPT_DIR/generate-corpus.sh" >&2
fi
QUERIES=100000

bin="$(binary_for_target "$TARGET" || true)"
[[ -z "$bin" ]] && emit_missing "$LANE_NAME" "$TARGET" && exit 1

case "$TARGET" in
    sqlite-mainline|turso)
        cmd=(bash -c "$bin :memory: < $WORKLOAD")
        ;;
    sqlite-leap-c|sqlite-leap-rust)
        # See bench/lanes/_wrap_sql.py for why per-statement wrapping is
        # required. Pre-2026-04-20 the whole workload was wrapped under
        # a single `statement ok` header and the runner failed fast on
        # the second statement.
        wrapped="$SCRIPT_DIR/workload.slt"
        if [[ ! -f "$wrapped" || "$WORKLOAD" -nt "$wrapped" ]]; then
            python3 "$BENCH_ROOT/lanes/_wrap_sql.py" "$WORKLOAD" "$wrapped" >&2
        fi
        cmd=("$bin" "$wrapped")
        ;;
esac

median_seconds="$(time_median 5 1 -- "${cmd[@]}")"
qps="$(python3 -c "print(int(${QUERIES}/${median_seconds}))")"
emit_csv "$LANE_NAME" "$TARGET" "$qps" "selects_per_second"
